package com.example.events;
import jakarta.persistence.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import jakarta.servlet.http.HttpSession;import jakarta.servlet.http.HttpServletRequest;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.context.annotation.*;import org.springframework.http.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.transaction.annotation.Transactional;import com.example.events.service.EventService;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import org.springframework.web.servlet.config.annotation.*;import jakarta.persistence.EntityManager;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@SpringBootApplication
public class EventEnrollmentApplication{
 public static void main(String[]a){SpringApplication.run(EventEnrollmentApplication.class,a);}
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain security(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).authorizeHttpRequests(a->a.anyRequest().permitAll()).build();}
 @Bean WebMvcConfigurer cors(){return new WebMvcConfigurer(){public void addCorsMappings(CorsRegistry r){r.addMapping("/api/**").allowedOriginPatterns("http://localhost:*","http://127.0.0.1:*").allowedMethods("GET","POST","PATCH","PUT","DELETE","OPTIONS").allowCredentials(true).allowedHeaders("*");}};}
 @RestController @RequestMapping("/api") @Transactional public static class Api{
  final EntityManager em;final PasswordEncoder encoder;final EventService eventService;Api(EntityManager e,PasswordEncoder p,EventService es){em=e;encoder=p;eventService=es;}
  Map<String,Object> userView(User u){return Map.of("id",u.id,"fullName",u.fullName,"email",u.email,"phone",u.phone,"role",u.role);}
  User current(HttpSession s){Object id=s.getAttribute("uid");if(id==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Please log in");User u=em.find(User.class,id);if(u==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Please log in");return u;}
  void admin(HttpSession s){if(!"ADMIN".equals(current(s).role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Admin access required");}
  Map<String,Object> eventView(Event e){Map<String,Object> m=new LinkedHashMap<>();m.put("id",e.id);m.put("title",e.title);m.put("description",e.description);m.put("category",Objects.toString(e.category,"Community"));m.put("dateTime",e.dateTime);m.put("registrationDeadline",e.registrationDeadline);m.put("venue",e.venue);m.put("price",e.price);m.put("capacity",e.capacity);m.put("availableSeats",e.availableSeats);m.put("status",e.status);return m;}
  Map<String,Object> enrollView(Enrollment x){Payment p=em.createQuery("select p from Payment p where p.enrollment.id=:id",Payment.class).setParameter("id",x.id).getResultStream().findFirst().orElse(null);Map<String,Object> m=new LinkedHashMap<>();m.put("id",x.id);m.put("registrationId",x.registrationId);m.put("participantName",x.participantName);m.put("participantEmail",x.participantEmail);m.put("participantPhone",x.participantPhone);m.put("eventTitle",x.event.title);m.put("eventDateTime",x.event.dateTime);m.put("amount",x.event.price);m.put("status",x.status);m.put("paymentStatus",p==null?"PENDING":p.status);return m;}
  @PostMapping("/auth/register") public Map<String,Object> register(@Valid @RequestBody Register r){if(em.createQuery("select count(u) from User u where lower(u.email)=lower(:e)",Long.class).setParameter("e",r.email).getSingleResult()>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");User u=new User();u.fullName=r.fullName.trim();u.email=r.email.trim().toLowerCase();u.phone=r.phone.trim();u.password=encoder.encode(r.password);em.persist(u);return userView(u);}
  @PostMapping("/auth/login") public Map<String,Object> login(@RequestBody Login l,HttpSession s,HttpServletRequest request){User u=em.createQuery("select u from User u where lower(u.email)=lower(:e)",User.class).setParameter("e",l.email).getResultStream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!encoder.matches(l.password,u.password))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");request.changeSessionId();s.setAttribute("uid",u.id);return userView(u);}
  @PostMapping("/auth/logout") public Map<String,String> logout(HttpSession s){s.invalidate();return Map.of("message","Signed out");}
  @GetMapping("/auth/me") public Map<String,Object> me(HttpSession s){return userView(current(s));}
  @GetMapping("/events") public List<Map<String,Object>> events(@RequestParam(required=false)String search,@RequestParam(required=false)String category){return eventService.upcoming(search,category).stream().map(this::eventView).toList();}
  @GetMapping("/events/{id}") public Map<String,Object> event(@PathVariable Long id){return eventView(em.find(Event.class,id)!=null?em.find(Event.class,id):missing());} Event missing(){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Event not found");}
  public record Register(@NotBlank @Size(max=120)String fullName,@NotBlank @Email String email,@NotBlank @Size(max=30)String phone,@NotBlank @Size(min=8,max=72)String password){} public record Login(String email,String password){} public record EnrollmentRequest(@NotNull Long eventId,@NotBlank String participantName,@NotBlank @Email String participantEmail,@NotBlank String participantPhone){} public record PayRequest(Boolean succeed){}
  @PostMapping("/enrollments") public Map<String,Object> enroll(@Valid @RequestBody EnrollmentRequest r,HttpSession s){User u=current(s);Event e=em.find(Event.class,r.eventId,LockModeType.PESSIMISTIC_WRITE);if(e==null||!"PUBLISHED".equals(e.status))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Event unavailable");if(e.dateTime.isBefore(LocalDateTime.now())||e.registrationDeadline.isBefore(LocalDateTime.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Registration has closed");if(e.availableSeats<1)throw new ResponseStatusException(HttpStatus.CONFLICT,"Event is full");if(em.createQuery("select count(x) from Enrollment x where x.user.id=:u and x.event.id=:e",Long.class).setParameter("u",u.id).setParameter("e",e.id).getSingleResult()>0)throw new ResponseStatusException(HttpStatus.CONFLICT,"You are already enrolled");e.availableSeats--;Enrollment x=new Enrollment();x.user=u;x.event=e;x.participantName=r.participantName.trim();x.participantEmail=r.participantEmail.trim();x.participantPhone=r.participantPhone.trim();x.registrationId="PENDING";em.persist(x);Payment p=new Payment();p.enrollment=x;p.amount=e.price;em.persist(p);em.flush();x.registrationId="GTH-"+String.format("%08d",x.id);return enrollView(x);}
  @GetMapping("/enrollments/{id}") public Map<String,Object> getEnrollment(@PathVariable Long id,HttpSession s){Enrollment x=em.find(Enrollment.class,id);if(x==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Enrollment not found");User u=current(s);if(!u.id.equals(x.user.id)&&!"ADMIN".equals(u.role))throw new ResponseStatusException(HttpStatus.FORBIDDEN);return enrollView(x);}
  @GetMapping("/enrollments/mine") public List<Map<String,Object>> mine(HttpSession s){User u=current(s);return em.createQuery("select x from Enrollment x where x.user.id=:id order by x.createdAt desc",Enrollment.class).setParameter("id",u.id).getResultList().stream().map(this::enrollView).toList();}
  @PostMapping("/payments/{id}") public Map<String,Object> payment(@PathVariable Long id,@RequestBody PayRequest r,HttpSession s){Enrollment x=em.find(Enrollment.class,id);if(x==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Enrollment not found");User u=current(s);if(!u.id.equals(x.user.id)&&!"ADMIN".equals(u.role))throw new ResponseStatusException(HttpStatus.FORBIDDEN);Payment p=em.createQuery("select p from Payment p where p.enrollment.id=:id",Payment.class).setParameter("id",id).getSingleResult();p.status=Boolean.TRUE.equals(r.succeed)?"SUCCESS":"FAILED";p.reference="SIM-"+UUID.randomUUID().toString().substring(0,12).toUpperCase();x.status=Boolean.TRUE.equals(r.succeed)?"CONFIRMED":"PENDING_PAYMENT";return enrollView(x);}
  @GetMapping("/admin/stats") public Map<String,Object> stats(HttpSession s){admin(s);Long ev=em.createQuery("select count(e) from Event e",Long.class).getSingleResult(),en=em.createQuery("select count(x) from Enrollment x",Long.class).getSingleResult(),pa=em.createQuery("select count(p) from Payment p where p.status='SUCCESS'",Long.class).getSingleResult();BigDecimal rev=em.createQuery("select coalesce(sum(p.amount),0) from Payment p where p.status='SUCCESS'",BigDecimal.class).getSingleResult();return Map.of("totalEvents",ev,"totalEnrollments",en,"successfulPayments",pa,"revenue",rev);}
  @GetMapping("/admin/events") public List<Map<String,Object>> adminEvents(HttpSession s){admin(s);return em.createQuery("select e from Event e order by e.dateTime",Event.class).getResultList().stream().map(this::eventView).toList();}
  @PostMapping("/admin/events") public Map<String,Object> createEvent(@RequestBody EventInput i,HttpSession s){admin(s);if(i.dateTime==null||i.registrationDeadline==null||i.dateTime.isBefore(i.registrationDeadline)||i.capacity<1||i.price==null||i.price.signum()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Check dates, price and capacity");Event e=new Event();e.title=i.title;e.description=i.description;e.category=i.category;e.dateTime=i.dateTime;e.registrationDeadline=i.registrationDeadline;e.venue=i.venue;e.price=i.price;e.capacity=i.capacity;e.availableSeats=i.capacity;e.status="PUBLISHED";em.persist(e);return eventView(e);}
  @PatchMapping("/admin/events/{id}") public Map<String,Object> editEvent(@PathVariable Long id,@RequestBody Map<String,Object> changes,HttpSession s){admin(s);Event e=em.find(Event.class,id);if(e==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Event not found");if(changes.containsKey("title"))e.title=Objects.toString(changes.get("title"));if(changes.containsKey("description"))e.description=Objects.toString(changes.get("description"));if(changes.containsKey("venue"))e.venue=Objects.toString(changes.get("venue"));if(changes.containsKey("category"))e.category=Objects.toString(changes.get("category"));if(changes.containsKey("status")){String status=Objects.toString(changes.get("status"));if(!List.of("PUBLISHED","CANCELLED").contains(status))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid event status");e.status=status;}return eventView(e);}
  public record EventInput(String title,String description,String category,String venue,LocalDateTime dateTime,LocalDateTime registrationDeadline,int capacity,BigDecimal price){}
  @PatchMapping("/admin/events/{id}/cancel") public Map<String,Object> cancel(@PathVariable Long id,HttpSession s){admin(s);Event e=em.find(Event.class,id);if(e==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);e.status="CANCELLED";return eventView(e);}
  @GetMapping("/admin/enrollments") public List<Map<String,Object>> adminEnrollments(HttpSession s){admin(s);return em.createQuery("select x from Enrollment x order by x.createdAt desc",Enrollment.class).getResultList().stream().map(this::enrollView).toList();}
 }
 @Bean CommandLineRunner seed(jakarta.persistence.EntityManagerFactory emf,PasswordEncoder encoder){return args->{var em=emf.createEntityManager();var tx=em.getTransaction();tx.begin();if(em.createQuery("select count(u) from User u",Long.class).getSingleResult()==0){User u=new User();u.fullName="Gather Administrator";u.email="admin@gather.local";u.phone="9999999999";u.password=encoder.encode("Admin123!");u.role="ADMIN";em.persist(u);}if(em.createQuery("select count(e) from Event e",Long.class).getSingleResult()==0){String[] titles={"Ideas in Good Company","The City We Want","Sunday Table Sessions"};String[] cats={"Community","Arts","Food"};String[] places={"The Commons, Bengaluru","Open House Studio, Bengaluru","Mango Tree Courtyard, Bengaluru"};for(int i=0;i<titles.length;i++){Event e=new Event();e.title=titles[i];e.category=cats[i];e.description="A welcoming gathering for curious people to share ideas, meet new friends and enjoy an inspiring afternoon together.";e.venue=places[i];e.dateTime=LocalDateTime.now().plusDays(25+i*14);e.registrationDeadline=e.dateTime.minusDays(2);e.capacity=40+i*10;e.availableSeats=e.capacity;e.price=BigDecimal.valueOf(i==1?499:0);e.status="PUBLISHED";em.persist(e);}}tx.commit();em.close();};}
 @RestControllerAdvice public static class Errors{@ExceptionHandler(ResponseStatusException.class) public ResponseEntity<Map<String,String>> status(ResponseStatusException e){return ResponseEntity.status(e.getStatusCode()).body(Map.of("message",Objects.toString(e.getReason(),"Request failed")));}@ExceptionHandler(Exception.class) public ResponseEntity<Map<String,String>> other(Exception e){return ResponseEntity.badRequest().body(Map.of("message",Objects.toString(e.getMessage(),"Invalid request")));}}
}







